// Compute ISO date strings for the lookback window.
// n8n execution context: $json contains domain + config from previous nodes.
const lookbackDays = $('Config — thresholds & domains').first().json.lookback_days || 30;

const now = new Date();
const endDate = now.toISOString().split('T')[0];  // YYYY-MM-DD (today)

const startDate = new Date(now);
startDate.setDate(startDate.getDate() - lookbackDays);
const startDateStr = startDate.toISOString().split('T')[0];

return [{
  json: {
    ...$input.item.json,
    start_date: startDateStr,
    end_date: endDate,
  }
}];

// ---------------------------------------------------------------------------
// Compute deliverability metrics from the SendGrid /v3/stats response.
//
// SendGrid returns an array of daily objects:
// [ { date: 'YYYY-MM-DD', stats: [{ metrics: { requests, delivered,
//     bounces, spam_reports, opens, unique_opens, ... } }] }, ... ]
//
// We compute:
//   bounce_rate   = sum(bounces)      / sum(requests)
//   spam_rate     = sum(spam_reports) / sum(requests)
//   open_rate_7d  = sum(unique_opens, last 7 days) / sum(delivered, last 7 days)
//   open_rate_30d = sum(unique_opens, all days)    / sum(delivered, all days)
//   open_rate_drop_ppt = open_rate_30d - open_rate_7d  (positive = drop)
// ---------------------------------------------------------------------------

const domain = $('Split per domain').item.json.domains || $input.item.json.domains;
const config = $('Config — thresholds & domains').first().json;

const stats = $input.item.json; // array of daily stat objects from SendGrid

let totalRequests = 0, totalDelivered = 0;
let totalBounces = 0, totalSpam = 0, totalUniqueOpens = 0;
let requests7d = 0, delivered7d = 0, uniqueOpens7d = 0;

const sevenDaysAgo = new Date();
sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

const days = Array.isArray(stats) ? stats : [];

for (const day of days) {
  const metrics = (day.stats && day.stats[0] && day.stats[0].metrics) || {};
  const req       = metrics.requests       || 0;
  const delivered = metrics.delivered      || 0;
  const bounces   = metrics.bounces        || 0;
  const spam      = metrics.spam_reports   || 0;
  const uOpens    = metrics.unique_opens   || 0;

  totalRequests    += req;
  totalDelivered   += delivered;
  totalBounces     += bounces;
  totalSpam        += spam;
  totalUniqueOpens += uOpens;

  const dayDate = new Date(day.date);
  if (dayDate >= sevenDaysAgo) {
    requests7d    += req;
    delivered7d   += delivered;
    uniqueOpens7d += uOpens;
  }
}

const bounceRate   = totalRequests > 0 ? totalBounces / totalRequests : 0;
const spamRate     = totalRequests > 0 ? totalSpam    / totalRequests : 0;
const openRate30d  = totalDelivered > 0 ? totalUniqueOpens / totalDelivered : 0;
const openRate7d   = delivered7d > 0   ? uniqueOpens7d    / delivered7d     : 0;
// Drop in percentage points (positive = open rate fell)
const openRateDrop = (openRate30d - openRate7d) * 100;

return [{
  json: {
    domain,
    bounce_rate:   bounceRate,
    spam_rate:     spamRate,
    open_rate_7d:  openRate7d,
    open_rate_30d: openRate30d,
    open_rate_drop_ppt: openRateDrop,
    total_requests: totalRequests,
    // Config thresholds (passed through for the IF node)
    bounce_threshold:    config.bounce_threshold,
    spam_threshold:      config.spam_threshold,
    open_rate_drop_ppt_threshold: config.open_rate_drop_pct,
    backend_url:         config.backend_url,
  }
}];

// Build one webhook call per breached threshold.
// Multiple thresholds can breach simultaneously — send a separate call
// per alert_type so each is logged individually in alert_log.

const d = $input.item.json;
const alerts = [];

if (d.bounce_rate > d.bounce_threshold) {
  alerts.push({
    domain:          d.domain,
    alert_type:      'bounce_rate_exceeded',
    metric_value:    d.bounce_rate,
    threshold_value: d.bounce_threshold,
    backend_url:     d.backend_url,
  });
}
if (d.spam_rate > d.spam_threshold) {
  alerts.push({
    domain:          d.domain,
    alert_type:      'spam_rate_exceeded',
    metric_value:    d.spam_rate,
    threshold_value: d.spam_threshold,
    backend_url:     d.backend_url,
  });
}
if (d.open_rate_drop_ppt > d.open_rate_drop_ppt_threshold) {
  alerts.push({
    domain:          d.domain,
    alert_type:      'open_rate_drop',
    metric_value:    d.open_rate_drop_ppt,
    threshold_value: d.open_rate_drop_ppt_threshold,
    backend_url:     d.backend_url,
  });
}

return alerts.map(a => ({ json: a }));

// Log that this domain is healthy (no thresholds breached).
const d = $input.item.json;
console.log(`[SendGrid Health] Domain '${d.domain}' OK — bounce=${(d.bounce_rate*100).toFixed(2)}% spam=${(d.spam_rate*100).toFixed(3)}% open_rate_7d=${(d.open_rate_7d*100).toFixed(1)}%`);
return [{ json: { status: 'healthy', domain: d.domain, bounce_rate: d.bounce_rate, spam_rate: d.spam_rate, open_rate_7d: d.open_rate_7d } }];
